class Solution { public:
 string clearStars(string s) { vector<int> pos[26]; vector<bool> dead(s.size());
 for(int i=0;i<(int)s.size();++i){ if(s[i]=='*'){dead[i]=true;for(int c=0;c<26;++c)if(!pos[c].empty()){dead[pos[c].back()]=true;pos[c].pop_back();break;}}else pos[s[i]-'a'].push_back(i);}
 string r;for(int i=0;i<(int)s.size();++i)if(!dead[i])r+=s[i];return r; }
};
